bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
import {setDefaultResultOrder} from 'node:dns';import {setDefaultAutoSelectFamily} from 'node:net';
import {createCreatorTelegramFetch} from '/opt/videobot/src/runtime/creatorEgress.mjs';
setDefaultResultOrder('ipv4first');setDefaultAutoSelectFamily(false);
const outbound=createCreatorTelegramFetch();
const e=process.env,token=readFileSync('/run/secrets/videobot_telegram_token','utf8').trim();
const db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
try{
 const q=await db.query("SELECT l.thumbnail_file_id,b.free_message_ids FROM videobot_post_receipts a JOIN videobot_listings l ON l.listing_id=a.listing_id JOIN videobot_post_receipts b ON b.listing_id=l.listing_id AND b.revision=l.revision WHERE a.paid_message_id=4691 AND a.free_message_ids=ARRAY[4689,4690]::bigint[] AND b.status='sent'");
 if(q.rowCount!==1)process.exit(61);
 const r=q.rows[0],id=Number(r.free_message_ids?.[0]);
 if(!Number.isSafeInteger(id)||id<1||!r.thumbnail_file_id)process.exit(62);
 const payload={chat_id:-1002373696859,message_id:id,media:{type:'photo',media:r.thumbnail_file_id,has_spoiler:true}};
 const response=await outbound.fetch((e.VIDEOBOT_LOCAL_API_URL??'https://api.telegram.org')+'/bot'+token+'/editMessageMedia',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload),signal:AbortSignal.timeout(30000)});
 const data=await response.json().catch(()=>null);
 if(data?.ok===true)process.exit(data.result?.has_media_spoiler===true?0:89);
 const reason=String(data?.description??'').toLowerCase();
 if(reason.includes('message is not modified'))process.exit(81);
 if(reason.includes('message can')&&reason.includes('edit'))process.exit(82);
 if(reason.includes('message to edit not found')||reason.includes('message_id_invalid'))process.exit(83);
 if(reason.includes('media')&&(reason.includes('invalid')||reason.includes('type')))process.exit(84);
 if(reason.includes('file')&&(reason.includes('invalid')||reason.includes('reference')))process.exit(85);
 if(reason.includes('not enough rights')||reason.includes('not enough permissions'))process.exit(86);
 if(response.status===400)process.exit(87);
 if(response.status===403)process.exit(88);
 process.exit(90);
}catch(e){process.exitCode=93}finally{await outbound.close();await db.end()}
JS
